/*
===============================================================================
 SMASH-VN: FILE BACKUP DỮ LIỆU SẢN PHẨM CŨ (ĐÃ SẮP XẾP LẠI ID TUẦN TỰ ĐẸP)
 Mô tả:
   - Toàn bộ 59 sản phẩm cũ được xếp lại ID tuần tự từ 1 đến 59.
   - Toàn bộ 119 biến thể cũ được xếp lại ID tuần tự từ 1 đến 119.
   - Toàn bộ liên kết ngoại (Ảnh, Thuộc tính, Phiếu nhập, Hóa đơn, Giỏ hàng, Đánh giá, Giảm giá) đều được map chuẩn xác.
   - Chạy script này bất cứ lúc nào để phục hồi dữ liệu cũ sạch đẹp.
===============================================================================
*/
USE [BadmintonShopDB1];
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET NOCOUNT ON;
BEGIN TRANSACTION;
BEGIN TRY
    PRINT N'1. Đang dọn dẹp dữ liệu sản phẩm cũ...';
    DELETE FROM [dbo].[CommentViolationLog];
    DELETE FROM [dbo].[HinhAnhDanhGia];
    DELETE FROM [dbo].[DanhGia];
    DELETE FROM [dbo].[GioHangChiTiet];
    DELETE FROM [dbo].[HoaDonChiTiet];
    DELETE FROM [dbo].[PhieuNhapChiTiet];
    DELETE FROM [dbo].[SanPhamYeuThich];
    DELETE FROM [dbo].[SanPham_DotGiamGia];
    DELETE FROM [dbo].[HinhAnhSanPham];
    DELETE FROM [dbo].[SanPhamChiTietThuocTinh];
    DELETE FROM [dbo].[SanPhamChiTiet];
    DELETE FROM [dbo].[SanPham];

    PRINT N'2. Đang nạp SanPham (ID 1 -> 59)...';
    SET IDENTITY_INSERT [dbo].[SanPham] ON;
    SET IDENTITY_INSERT [dbo].[SanPham] OFF;
    DBCC CHECKIDENT ('[dbo].[SanPham]', RESEED, 59);

    PRINT N'3. Đang nạp SanPhamChiTiet (ID 1 -> 119)...';
    SET IDENTITY_INSERT [dbo].[SanPhamChiTiet] ON;
    SET IDENTITY_INSERT [dbo].[SanPhamChiTiet] OFF;
    DBCC CHECKIDENT ('[dbo].[SanPhamChiTiet]', RESEED, 119);

    PRINT N'4. Đang nạp HinhAnhSanPham (220 ảnh)...';
    SET IDENTITY_INSERT [dbo].[HinhAnhSanPham] ON;
    SET IDENTITY_INSERT [dbo].[HinhAnhSanPham] OFF;
    DBCC CHECKIDENT ('[dbo].[HinhAnhSanPham]', RESEED, 220);

    PRINT N'5. Đang nạp SanPhamChiTietThuocTinh (292 dòng)...';
    SET IDENTITY_INSERT [dbo].[SanPhamChiTietThuocTinh] ON;
    SET IDENTITY_INSERT [dbo].[SanPhamChiTietThuocTinh] OFF;
    DBCC CHECKIDENT ('[dbo].[SanPhamChiTietThuocTinh]', RESEED, 292);

    PRINT N'6. Đang nạp PhieuNhapChiTiet...';
    SET IDENTITY_INSERT [dbo].[PhieuNhapChiTiet] ON;
    SET IDENTITY_INSERT [dbo].[PhieuNhapChiTiet] OFF;
    DBCC CHECKIDENT ('[dbo].[PhieuNhapChiTiet]', RESEED, 5);

    PRINT N'7. Đang nạp HoaDonChiTiet...';
    SET IDENTITY_INSERT [dbo].[HoaDonChiTiet] ON;
    SET IDENTITY_INSERT [dbo].[HoaDonChiTiet] OFF;
    DBCC CHECKIDENT ('[dbo].[HoaDonChiTiet]', RESEED, 36);

    PRINT N'8. Đang nạp GioHangChiTiet...';
    SET IDENTITY_INSERT [dbo].[GioHangChiTiet] ON;
    SET IDENTITY_INSERT [dbo].[GioHangChiTiet] OFF;
    DBCC CHECKIDENT ('[dbo].[GioHangChiTiet]', RESEED, 2);

    PRINT N'9. Đang nạp DanhGia...';
    SET IDENTITY_INSERT [dbo].[DanhGia] ON;

', N'2026-09-04 14:43:29', 0, 0, N'2026-09-07 08:35:04', 1, 1);

', N'2026-09-04 14:57:27', 0, 0, N'2026-09-07 16:28:24', NULL, 0);
    SET IDENTITY_INSERT [dbo].[DanhGia] OFF;
    DBCC CHECKIDENT ('[dbo].[DanhGia]', RESEED, 7);

    PRINT N'10. Đang nạp SanPham_DotGiamGia...';

    PRINT N'11. Đang nạp CommentViolationLog...';
    SET IDENTITY_INSERT [dbo].[CommentViolationLog] ON;

', N'***
', N'MEDIUM', 1, N'2026-09-04 14:43:29', N'2026-09-04 14:43:29');

', N'***
', N'MEDIUM', 1, N'2026-09-04 14:49:54', N'2026-09-04 14:49:54');

', N'***
', N'MEDIUM', 1, N'2026-09-04 15:32:01', N'2026-09-04 15:32:01');

', N'***
', N'MEDIUM', 1, N'2026-09-07 08:33:24', N'2026-09-07 08:33:24');

', N'***
', N'MEDIUM', 1, N'2026-09-07 08:35:04', N'2026-09-07 08:35:04');

', N'***
', N'MEDIUM', 2, N'2026-09-07 16:28:24', N'2026-09-07 16:28:24');
    SET IDENTITY_INSERT [dbo].[CommentViolationLog] OFF;
    DBCC CHECKIDENT ('[dbo].[CommentViolationLog]', RESEED, 15);

    COMMIT TRANSACTION;
    PRINT N'===========================================================';
    PRINT N'===> ĐÃ KHÔI PHỤC THÀNH CÔNG DỮ LIỆU CŨ VỚI ID ĐẸP TUẦN TỰ!';
    PRINT N'===========================================================';
END TRY
BEGIN CATCH
    ROLLBACK TRANSACTION;
    PRINT N'LỖI KHI KHÔI PHỤC: ' + ERROR_MESSAGE();
    THROW;
END CATCH;
GO